(()=>{
'use strict';const $=s=>document.querySelector(s),core=window.AverageRateLesson,num=window.LinearLesson;
function math(host,tex){const e=document.createElement('span');e.dataset.tex=tex;host.replaceChildren(e);}
function fmt(x){return String(Object.is(x,-0)?0:x).replace('.','{,}');}
const formulas={square:String.raw`f(x)=x^2`,linear:String.raw`f(x)=2x+1`,decreasing:String.raw`f(x)=12-2x`,hump:String.raw`f(x)=4-(x-2)^2`};
let grid='';for(let x=-2;x<=4;x++){const p=core.point(x,0);grid+=`<line x1="${p.x}" x2="${p.x}" y1="30" y2="310" class="${x===0?'wave-axis':'wave-grid-line'}"/><text x="${p.x}" y="332" text-anchor="middle" class="wave-grid-label">${x}</text>`;}for(let y=-12;y<=16;y+=4){const p=core.point(0,y);grid+=`<line x1="50" x2="610" y1="${p.y}" y2="${p.y}" class="${y===0?'wave-axis':'wave-grid-line'}"/><text x="42" y="${p.y+5}" text-anchor="end" class="wave-grid-label">${y}</text>`;}$('#rate-grid').innerHTML=grid;
function draw(){const kind=$('#rate-kind').value,a=Number($('#rate-a').value)/2,b=Number($('#rate-b').value)/2,t=core.measure(kind,a,b),p=core.point(a,t.fa),q=core.point(b,t.fb);$('#a-output').value=String(a).replace('.',',');$('#b-output').value=String(b).replace('.',',');$('#rate-a').setAttribute('aria-valuetext',String(a));$('#rate-b').setAttribute('aria-valuetext',String(b));math($('#rate-formula'),formulas[kind]);$('#rate-curve').setAttribute('d',core.curve(kind).map((p,i)=>`${i?'L':'M'}${p.x} ${p.y}`).join(' '));for(const [id,v]of [['point-p',p],['point-q',q]]){$('#'+id).setAttribute('cx',v.x);$('#'+id).setAttribute('cy',v.y);}$('#point-q').setAttribute('visibility',t.rate===null?'hidden':'visible');if(t.rate===null){$('#rate-secant').setAttribute('d','');$('#rate-steps').setAttribute('d','');}else{const start=core.point(-2,t.fa+t.rate*(-2-a)),end=core.point(4,t.fa+t.rate*(4-a));$('#rate-secant').setAttribute('d',`M${start.x} ${start.y}L${end.x} ${end.y}`);$('#rate-steps').setAttribute('d',`M${p.x} ${p.y}L${q.x} ${p.y}L${q.x} ${q.y}`);}math($('#rate-values'),String.raw`\begin{aligned}P&=(${fmt(a)},${fmt(t.fa)}),\quad Q=(${fmt(b)},${fmt(t.fb)})\\\Delta x&=b-a=${fmt(t.dx)}\\\Delta y&=f(b)-f(a)=${fmt(t.dy)}\end{aligned}`);if(t.rate===null){math($('#rate-result'),String.raw`\text{Laju rata-rata tidak terdefinisi karena }b-a=0`);$('#rate-note').textContent='Kedua masukan berimpit. Rasio perubahan mempunyai pembagi nol, sehingga kita tidak menggambar garis sekan dari dua titik berbeda dan tidak menyimpulkan lajunya nol.';}else{math($('#rate-result'),String.raw`\begin{aligned}m&=\frac{f(b)-f(a)}{b-a}\\&=\frac{(${fmt(t.fb)})-(${fmt(t.fa)})}{(${fmt(b)})-(${fmt(a)})}=${fmt(t.rate)}\end{aligned}`);$('#rate-note').textContent=(a>b?'Urutan kedua titik dibalik: pembilang dan penyebut sama-sama berubah tanda, sehingga laju rata-rata tetap sama. ':t.rate===0?'Keluaran kedua titik sama sehingga laju rata-ratanya nol. Perhatikan bahwa kurva tetap dapat berubah di antara kedua titik. ':t.rate>0?'Dari masukan yang lebih kecil ke yang lebih besar, keluaran akhirnya lebih besar. ':'Dari masukan yang lebih kecil ke yang lebih besar, keluaran akhirnya lebih kecil. ')+(kind==='linear'?'Untuk fungsi linear ini, semua pasangan masukan berbeda memberi laju dua.':kind==='decreasing'?'Untuk fungsi linear ini, semua pasangan masukan berbeda memberi laju negatif dua.':'Pada fungsi melengkung, mengganti interval dapat mengubah laju rata-rata.');}$('#rate-plot').setAttribute('aria-label',`Grafik ${kind==='square'?'kuadrat':kind==='hump'?'lengkung dengan puncak di dua, empat':'linear'}. Titik pertama (${a}, ${t.fa}), titik kedua (${b}, ${t.fb}). Perubahan masukan ${t.dx}, perubahan keluaran ${t.dy}. ${t.rate===null?'Laju rata-rata tidak terdefinisi; dua masukan sama.':'Kemiringan garis sekan atau laju rata-rata '+t.rate+'.'}`);}
for(const id of ['rate-kind','rate-a','rate-b'])$('#'+id).addEventListener('input',draw);document.querySelectorAll('[data-rate]').forEach(e=>e.addEventListener('click',()=>{if(e.dataset.rate==='reverse'){const a=$('#rate-a').value;$('#rate-a').value=$('#rate-b').value;$('#rate-b').value=a;}else{const values={initial:[2,6],zero:[-2,2],equal:[2,2]}[e.dataset.rate];$('#rate-kind').value='square';$('#rate-a').value=values[0];$('#rate-b').value=values[1];}draw();}));draw();
const questions=[{tex:String.raw`f(x)=x^2,\quad a=1,\quad b=3`,prompt:'Berapa laju perubahan rata-rata fungsi pada kedua masukan ini?',n:4,d:1,hint:'Hitung f tiga dikurangi f satu, lalu bagi tiga dikurangi satu.',why:'Sembilan dikurangi satu dibagi tiga dikurangi satu menghasilkan delapan per dua, yaitu empat.'},{tex:String.raw`T(0)=80,\quad T(10)=50`,prompt:'Suhu dalam derajat Celsius dan waktu dalam menit. Berapa laju perubahan rata-rata suhu?',n:-3,d:1,hint:'Perubahan suhu adalah suhu akhir dikurangi suhu awal.',why:'Lima puluh dikurangi delapan puluh adalah negatif tiga puluh. Dibagi sepuluh menit, hasilnya negatif tiga derajat Celsius per menit.'},{tex:String.raw`f(x)=x^2,\quad a=-1,\quad b=1`,prompt:'Berapa laju perubahan rata-ratanya?',n:0,d:1,hint:'Nilai fungsi pada kedua masukan sama-sama satu.',why:'Perubahan keluaran nol, sedangkan perubahan masukan dua. Rasionya nol, walaupun kurva turun lalu naik di tengah interval.'}];const solved=new Set();function report(i,ok,text){const e=$('#feedback'+i);e.className='feedback '+(ok?'correct':'incorrect');e.textContent=text;if(ok)solved.add(i);$('#progress').textContent=`${solved.size} dari 6 latihan sudah dijawab tepat.`;}
$('#questions').innerHTML=questions.map((q,i)=>`<div class="question"><h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><p>${q.prompt}</p><form data-question="${i}"><label for="answer${i}">Jawabanmu</label><div class="answer-line"><input id="answer${i}" type="text" required autocomplete="off" aria-describedby="feedback${i}"><button class="button" type="submit">Periksa jawaban</button></div></form><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Butuh petunjuk?</summary><p>${q.hint}</p></details><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details></div>`).join('');document.querySelectorAll('form[data-question]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const i=Number(form.dataset.question),q=questions[i],a=num.parseAnswer($('#answer'+i).value),ok=num.equalAnswer(a,num.rational(q.n,q.d));report(i,ok,ok?'Tepat. '+q.why:!a?'Tulis bilangan yang diminta tanpa satuan, misalnya 4 atau -3.':'Belum tepat. Periksa selisih keluaran, selisih masukan, dan urutan pengurangannya.');}));
const choices=[{tex:String.raw`f(1)=1,\quad f(3)=9`,prompt:'Apa perbedaan laju rata-rata dan rata-rata dua nilai keluaran?',options:[{text:'Keduanya pasti lima.'},{text:'Laju rata-rata empat, sedangkan rata-rata dua nilai keluaran lima.'},{text:'Laju rata-rata lima, sedangkan rata-rata dua nilai keluaran empat.'}],answer:1,why:'Laju memakai selisih keluaran dibagi selisih masukan. Rata-rata dua nilai memakai jumlah kedua keluaran dibagi dua.'},{tex:String.raw`a=b`,prompt:'Apa yang dapat dikatakan tentang rasio laju rata-rata?',options:[{text:'Tidak terdefinisi karena perubahan masukan nol.'},{text:'Selalu nol karena titiknya sama.'},{text:'Sama dengan nilai fungsi di titik itu.'}],answer:0,why:'Pembagi b dikurangi a sama dengan nol. Laju rata-rata memerlukan dua masukan berbeda.'},{tex:String.raw`r_1=2,\ t_1=1;\quad r_2=8,\ t_2=3`,prompt:'Laju dalam satuan per menit dan durasi dalam menit. Berapa laju rata-rata untuk seluruh empat menit?',options:[{text:'Lima satuan per menit.'},{text:'Sepuluh satuan per menit.'},{text:'Enam setengah satuan per menit.'}],answer:2,why:'Perubahan total dua kali satu ditambah delapan kali tiga adalah dua puluh enam. Dibagi empat menit, hasilnya enam setengah satuan per menit.'}];for(let j=0;j<choices.length;j++){const i=j+3,q=choices[j],box=document.createElement('div');box.className='question';box.innerHTML=`<h3 data-no-equation>Latihan ${i+1}</h3><p data-tex="${q.tex}"></p><fieldset><legend>${q.prompt}</legend>${q.options.map((o,k)=>`<label class="choice"><input type="radio" name="choice${i}" value="${k}" ${o.label?'aria-label="'+o.label+'"':''}>${o.tex?'<span data-tex="'+o.tex+'"></span>':o.text}</label>`).join('')}</fieldset><button type="button" class="button" data-check="${i}">Periksa jawaban</button><p class="feedback" id="feedback${i}" role="status"></p><details><summary>Lihat pembahasan</summary><p>${q.why}</p></details>`;$('#questions').append(box);box.querySelector('button').addEventListener('click',()=>{const a=$(`[name="choice${i}"]:checked`),ok=!!a&&Number(a.value)===q.answer;report(i,ok,!a?'Pilih jawaban dahulu.':(ok?'Tepat. ':'Belum tepat. ')+q.why);});}
const storage={get(k){try{return localStorage.getItem('fondasi-average-rate-'+k)}catch{return null}},set(k,v){try{localStorage.setItem('fondasi-average-rate-'+k,v);return true}catch{return false}}};$('#reflection').value=storage.get('reflection')||'';$('#reflection').addEventListener('input',()=>{$('#save-note').textContent=storage.set('reflection',$('#reflection').value)?'Catatan tersimpan di peramban ini.':'Catatan belum dapat disimpan; salin jika diperlukan.';});function complete(saved){$('#complete').textContent='Bacaan sudah ditandai selesai ✓';$('#complete-note').textContent=saved?'Kemajuan tersimpan di peramban ini. Kamu bisa mencoba kembali kapan saja.':'Bacaan selesai; kemajuan belum dapat disimpan di peramban ini.';}$('#complete').addEventListener('click',()=>complete(storage.set('complete','yes')));if(storage.get('complete')==='yes')complete(true);
})();